parameters.jsCode:
const allowedCategories = new Set([
  'groceries', 'dining', 'transport', 'housing', 'utilities',
  'subs', 'shopping', 'entertainment', 'health', 'other',
]);

return $input.all().map((item, index) => {
  try {
    const msg = item.json.message?.content;
    if (typeof msg !== 'string' || msg.trim() === '') {
      throw new Error('empty or missing content from Ollama');
    }
    let parsed;
    try {
      parsed = JSON.parse(msg);
    } catch {
      throw new Error('malformed or incomplete JSON from Ollama');
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('expected a receipt object');
    }
    if (typeof parsed.date !== 'string' || parsed.date.trim() === '') {
      throw new Error('missing date');
    }
    const date = parsed.date.trim();
    const timestamp = Date.parse(date);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(timestamp)
        || new Date(timestamp).toISOString().slice(0, 10) !== date) {
      throw new Error('invalid date; expected a real YYYY-MM-DD date');
    }
    if (typeof parsed.merchant !== 'string' || parsed.merchant.trim() === '') {
      throw new Error('missing merchant');
    }
    if (parsed.total === null || parsed.total === undefined
        || (typeof parsed.total === 'string' && parsed.total.trim() === '')) {
      throw new Error('missing total');
    }
    if (typeof parsed.total !== 'number' || !Number.isFinite(parsed.total)) {
      throw new Error('invalid total; expected a finite number');
    }
    if (typeof parsed.currency !== 'string' || parsed.currency.trim() === '') {
      throw new Error('missing currency');
    }
    const currency = parsed.currency.trim().toUpperCase();
    if (!['USD', 'EUR'].includes(currency)) {
      throw new Error('unsupported currency; expected USD or EUR');
    }
    if (typeof parsed.category !== 'string' || parsed.category.trim() === '') {
      throw new Error('missing category');
    }
    const category = parsed.category.trim().toLowerCase();
    if (!allowedCategories.has(category)) {
      throw new Error('invalid category; expected one of ' + [...allowedCategories].join(', '));
    }
    return {
      json: { date, merchant: parsed.merchant.trim(), total: parsed.total, currency, category, _error: false },
      pairedItem: { item: index },
    };
  } catch (e) {
    return {
      json: { _error: true, error: 'Receipt rejected: ' + e.message },
      pairedItem: { item: index },
    };
  }
});
